class Solution {
public:
    vector<int> resultsArray(vector<vector<int>>& queries, int k) {
        priority_queue<int> pq;
        vector<int> ans;
        for (const auto& q : queries) {
            int d = abs(q[0]) + abs(q[1]);
            if (pq.size() < k) {
                pq.push(d);
            } else if (d < pq.top()) {
                pq.pop();
                pq.push(d);
            }
            ans.push_back(pq.size() == k ? pq.top() : -1);
        }
        return ans;
    }
};

class Solution {
    public int[] resultsArray(int[][] queries, int k) {
        PriorityQueue<Integer> pq = new PriorityQueue<>(Collections.reverseOrder());
        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; ++i) {
            int d = Math.abs(queries[i][0]) + Math.abs(queries[i][1]);
            if (pq.size() < k) {
                pq.offer(d);
            } else if (d < pq.peek()) {
                pq.poll();
                pq.offer(d);
            }
            ans[i] = pq.size() == k ? pq.peek() : -1;
        }
        return ans;
    }
}

var resultsArray = function(queries, k) {
    // Binary insertion or custom heap for max-heap of size k
    const pq = []; // sorted ascending
    const ans = [];
    for (const [x, y] of queries) {
        const d = Math.abs(x) + Math.abs(y);
        // binary insert into sorted array of size up to k
        let l = 0, r = pq.length;
        while (l < r) {
            const mid = Math.floor((l + r) / 2);
            if (pq[mid] < d) l = mid + 1;
            else r = mid;
        }
        pq.splice(l, 0, d);
        if (pq.length > k) {
            pq.pop();
        }
        ans.push(pq.length === k ? pq[k - 1] : -1);
    }
    return ans;
};
